class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0

        # Try every possible subarray [i, j]
        for i in range(n):
            for j in range(i, n):
                # Initialize variables for checking if remaining array is strictly increasing
                ok = True
                lst = -1  # Last element seen in remaining array

                # Check each position k
                for k in range(n):
                    if i <= k <= j:
                        # k is within the subarray being removed, so we just update lst
                        lst = nums[k]
                    else:
                        # k is outside the subarray, so we need to check if remaining array is strictly increasing
                        if lst >= nums[k]:
                            ok = False
                            break
                        else:
                            lst = nums[k]

                # If the remaining array is strictly increasing, increment answer
                if ok:
                    ans += 1

        return ans

