class Solution:
    def findMissingAndRepeatedValues(self, grid: List[List[int]]) -> List[int]:
        n = len(grid)
        fre = [0] * (n * n + 1)

        # Count frequency of each number
        for row in grid:
            for num in row:
                fre[num] += 1

        rep = 0
        mis = 0

        # Find repeating and missing numbers
        for j in range(1, n * n + 1):
            if fre[j] == 0:
                mis = j
            elif fre[j] == 2:
                rep = j

        return [rep, mis]

