completion:
class Solution:
    def findIntersectionValues(self, nums1: List[int], nums2: List[int]) -> List[int]:
        # Convert nums2 to a set for O(1) lookup
        set_nums2 = set(nums2)
        # Convert nums1 to a set for O(1) lookup
        set_nums1 = set(nums1)

        c1 = 0  # Count of elements in nums1 that appear in nums2
        c2 = 0  # Count of elements in nums2 that appear in nums1

        # Check each element in nums1
        for num in nums1:
            if num in set_nums2:
                c1 += 1

        # Check each element in nums2
        for num in nums2:
            if num in set_nums1:
                c2 += 1

        return [c1, c2]

