class Solution:
    def findPeaks(self, mountain: List[int]) -> List[int]:
        res = []
        for i in range(1, len(mountain) - 1):
            if mountain[i] > mountain[i-1] and mountain[i] > mountain[i+1]:
                res.append(i)
        return res

class Solution:
    def areSimilar(self, mat: List[List[int]], k: int) -> bool:
        # For each row in the matrix
        for row in mat:
            n = len(row)
            # Check if shifting right by k positions leaves the row unchanged
            # This means for each position i, row[i] should equal row[(i+k) % n]
            for i in range(n):
                if row[i] != row[(i + k) % n]:
                    return False
        return True

