class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        maxXor = 0
        n = len(nums)

        for start in range(n):
            for end in range(start, n):
                x = nums[start]
                y = nums[end]

                # Check if it's a strong pair
                if abs(x - y) <= min(x, y):
                    currentXor = x ^ y
                    if currentXor > maxXor:
                        maxXor = currentXor

        return maxXor

