class Solution:
    def distributeCandies(self, n: int, limit: int) -> int:
        ans = 0
        # Iterate through possible values for child 1
        for c1 in range(0, limit + 1):
            # Iterate through possible values for child 2
            for c2 in range(0, limit + 1):
                # Calculate remaining candies for child 3
                c3 = n - c1 - c2
                # Check if child 3's candies are valid (non-negative and within limit)
                if c3 >= 0 and c3 <= limit:
                    ans += 1
        return ans

