class Solution:
    def findChampion(self, grid: List[List[int]]) -> int:
        n = len(grid)

        # Check each team i
        for i in range(n):
            is_champion = True
            # Check if any team j is stronger than team i
            for j in range(n):
                if i != j and grid[j][i] == 1:  # team j is stronger than team i
                    is_champion = False
                    break

            # If team i is champion, return it
            if is_champion:
                return i

        # If no champion found, return -1 (though problem guarantees one exists)
        return -1

