class Solution:
    def findKOr(self, nums: List[int], k: int) -> int:
        res = 0
        # Check each bit position from 0 to 31
        for i in range(32):
            n = 1 << i  # This is equivalent to 2^i
            count = 0
            # Count how many numbers have this bit set
            for num in nums:
                if num & n != 0:
                    count += 1
            # If at least k numbers have this bit set, include it in result
            if count >= k:
                res += n
        return res

