class Solution:
    def minimumSum(self, nums: List[int]) -> int:
        n = len(nums)
        ans = float('inf')

        # Iterate through all possible triplets (i, j, k) where i < j < k
        for i in range(n - 2):
            for j in range(i + 1, n - 1):
                for k in range(j + 1, n):
                    # Check if this forms a mountain triplet
                    if nums[i] < nums[j] and nums[k] < nums[j]:
                        # Update minimum sum if this is smaller
                        current_sum = nums[i] + nums[j] + nums[k]
                        ans = min(ans, current_sum)

        # Return -1 if no mountain triplet found, otherwise return minimum sum
        return ans if ans != float('inf') else -1

