completion:
class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        # Set to keep track of collected elements
        collected = set()
        operations = 0

        # Process from right to left
        for i in range(len(nums) - 1, -1, -1):
            # Check if current element is in range [1, k]
            if 1 <= nums[i] <= k:
                collected.add(nums[i])
                operations += 1

            # Check if we've collected all elements from 1 to k
            if len(collected) == k:
                return operations

        # This should never happen given the constraints
        return operations

