class Solution:
    def sumIndicesWithKSetBits(self, nums: List[int], k: int) -> int:
        total_sum = 0
        for i in range(len(nums)):
            # Count the number of set bits in the binary representation of index i
            set_bits_count = bin(i).count('1')
            # If the count equals k, add the corresponding element to the sum
            if set_bits_count == k:
                total_sum += nums[i]
        return total_sum

