class Solution:
    def minimumRightShifts(self, nums: List[int]) -> int:
        n = len(nums)

        # Check if last element >= first element
        if nums[-1] >= nums[0]:
            broken = n
        else:
            broken = 0

        # Iterate from n-1 down to 1
        for i in range(n - 1, 0, -1):
            if nums[i] < nums[i - 1]:
                if broken != 0:
                    return -1
                broken = i

        return n - broken

