class Solution:
    def furthestDistanceFromOrigin(self, moves: str) -> int:
        count_L = moves.count('L')
        count_R = moves.count('R')
        count_under = moves.count('_')

        # The maximum distance is achieved by always going in the direction
        # that maximizes the absolute distance from origin
        # If more L's than R's, use all underscores as L's
        # If more R's than L's, use all underscores as R's
        # If equal, it doesn't matter

        if count_L > count_R:
            return count_L + count_under - count_R
        elif count_R > count_L:
            return count_R + count_under - count_L
        else:
            return count_under

