class Solution:
    def maxSum(self, nums: List[int]) -> int:
        from collections import defaultdict

        max_by_digit = defaultdict(int)
        max_sum = -1

        for num in nums:
            # Extract maximum digit from current number
            digit = max(str(num))

            # Check if we've seen this digit before
            if digit in max_by_digit:
                # Update max_sum if current sum is better
                max_sum = max(max_sum, max_by_digit[digit] + num)
            else:
                # Store the current number as the maximum for this digit
                max_by_digit[digit] = num

        return max_sum

