class Solution:
    def splitWordsBySeparator(self, words: List[str], separator: str) -> List[str]:
        ans = []
        for word in words:
            # Split the current word by separator
            parts = word.split(separator)
            # Append each part to ans (empty strings will be included initially)
            for part in parts:
                if part:  # Only add non-empty strings
                    ans.append(part)
        return ans

