class Solution:
    def isGood(self, nums: List[int]) -> bool:
        n = max(nums)
        if len(nums) != n + 1:
            return False

        # Count occurrences of each number
        count = {}
        for num in nums:
            count[num] = count.get(num, 0) + 1

        # Check if numbers 1 to n-1 appear exactly once
        for i in range(1, n):
            if i not in count or count[i] != 1:
                return False

        # Check if n appears exactly twice
        if count.get(n, 0) != 2:
            return False

        return True

