completion:
class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        # Calculate the XOR of all elements in nums
        current_xor = 0
        for num in nums:
            current_xor ^= num

        # XOR the result with k to find the difference
        # This gives us the bits that need to be flipped
        diff = current_xor ^ k

        # Count the number of 1's in the binary representation
        # This equals the minimum operations required
        return bin(diff).count('1')

