from collections import deque

class Solution:
    def minimumOperationsToMakeEqual(self, x: int, y: int) -> int:
        if x == y:
            return 0

        queue = deque([(x, 0)])
        seen = set([x])

        while queue:
            current, steps = queue.popleft()

            # Try increment by 1
            next_val = current + 1
            if next_val == y:
                return steps + 1
            if next_val not in seen:
                seen.add(next_val)
                queue.append((next_val, steps + 1))

            # Try decrement by 1
            next_val = current - 1
            if next_val == y:
                return steps + 1
            if next_val not in seen and next_val > 0:  # Ensure positive integer
                seen.add(next_val)
                queue.append((next_val, steps + 1))

            # Try divide by 11
            if current % 11 == 0:
                next_val = current // 11
                if next_val == y:
                    return steps + 1
                if next_val not in seen:
                    seen.add(next_val)
                    queue.append((next_val, steps + 1))

            # Try divide by 5
            if current % 5 == 0:
                next_val = current // 5
                if next_val == y:
                    return steps + 1
                if next_val not in seen:
                    seen.add(next_val)
                    queue.append((next_val, steps + 1))

        return -1  # Should not reach here with valid inputs

