class Solution:
    def maximizeSquareArea(self, m: int, n: int, hFences: List[int], vFences: List[int]) -> int:
        MOD = 10**9 + 7

        # Add boundary fences
        hFences.append(1)
        hFences.append(m)
        vFences.append(1)
        vFences.append(n)

        # Sort fences
        hFences.sort()
        vFences.sort()

        # Calculate all horizontal differences
        horizontal_diffs = set()
        for i in range(len(hFences)):
            for j in range(i + 1, len(hFences)):
                diff = hFences[j] - hFences[i]
                horizontal_diffs.add(diff)

        # Calculate all vertical differences
        vertical_diffs = set()
        for i in range(len(vFences)):
            for j in range(i + 1, len(vFences)):
                diff = vFences[j] - vFences[i]
                vertical_diffs.add(diff)

        # Find maximum common difference
        max_diff = -1
        for diff in vertical_diffs:
            if diff in horizontal_diffs:
                max_diff = max(max_diff, diff)

        # Return result
        if max_diff == -1:
            return -1
        else:
            return (max_diff * max_diff) % MOD

