class Solution:
    def divideArray(self, nums: List[int], k: int) -> List[List[int]]:
        nums.sort()
        n = len(nums) // 3
        ans = []

        for i in range(n):
            # Check if the difference between the largest and smallest in current chunk exceeds k
            if nums[3*i + 2] - nums[3*i] > k:
                return []

            # Append current chunk to answer
            ans.append(nums[3*i:3*i+3])

        return ans

