class Solution:
    def minimumCost(self, nums: List[int]) -> int:
        # Sort the array
        nums.sort()

        # Define palindrome function
        def is_palindrome(x):
            s = str(x)
            return s == s[::-1]

        # Initialize left and right pointers to middle
        n = len(nums)
        left = nums[n // 2]
        right = nums[n // 2]

        # Two pointers approach
        while True:
            # Check if left is palindromic
            if not is_palindrome(left):
                left -= 1
            else:
                # Check if right is palindromic
                if not is_palindrome(right):
                    right += 1
                else:
                    # Both are palindromic, calculate costs
                    cost_left = sum(abs(x - left) for x in nums)
                    cost_right = sum(abs(x - right) for x in nums)
                    return min(cost_left, cost_right)

