completion:
class Solution:
    def getGoodIndices(self, variables: List[List[int]], target: int) -> List[int]:
        ans = []
        for i in range(len(variables)):
            a, b, c, m = variables[i]
            # Calculate (a^b % 10)^c % m
            result = pow(pow(a, b, 10), c, m)
            if result == target:
                ans.append(i)
        return ans

class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        maxVal = max(nums)
        count = 0
        left = 0
        res = 0

        for right in range(len(nums)):
            # If current element is maxVal, increment count
            if nums[right] == maxVal:
                count += 1

            # If we have at least k occurrences of maxVal
            while count >= k:
                # If left element is also maxVal, decrement count
                if nums[left] == maxVal:
                    count -= 1
                left += 1

            # Add the number of valid subarrays ending at current position
            res += left

        return res

