class Solution:
    def maximumXorProduct(self, a: int, b: int, n: int) -> int:
        mod = 10**9 + 7

        # Iterate through each bit position from 0 to n-1
        for i in range(n):
            # Calculate what happens if we flip bit i in both a and b
            t1 = a ^ (1 << i)
            t2 = b ^ (1 << i)

            # Check if flipping this bit improves the product
            if t1 * t2 > a * b:
                a = t1
                b = t2

        return (a * b) % mod

