class Solution:
    def findChampion(self, n: int, edges: List[List[int]]) -> int:
        # Initialize winner as a set of all teams from 0 to n-1
        winner = set(range(n))

        # For each edge in edges
        for edge in edges:
            # Discard the weaker team (which is edge[1])
            winner.discard(edge[1])

        # Check if there's a unique champion
        if len(winner) > 1:
            return -1
        elif len(winner) == 1:
            return list(winner)[0]
        else:
            # This shouldn't happen given the constraints
            return -1

class Solution:
    def minSum(self, nums1: List[int], nums2: List[int]) -> int:
        sum1 = 0
        cnt1 = 0
        sum2 = 0
        cnt2 = 0

        # Calculate sum and count of zeros for nums1
        for ele in nums1:
            if ele == 0:
                cnt1 += 1
            else:
                sum1 += ele

        # Calculate sum and count of zeros for nums2
        for ele in nums2:
            if ele == 0:
                cnt2 += 1
            else:
                sum2 += ele

        # If both arrays have no zeros, they must already have equal sum
        if cnt1 == 0 and cnt2 == 0:
            return sum1 if sum1 == sum2 else -1

        # If nums1 has no zeros, we can only increase nums2 if needed
        if cnt1 == 0:
            # We can only increase nums2 if sum2 < sum1 + cnt1
            # But since we can't decrease nums1, if sum1 > sum2 + cnt2, impossible
            # Actually, we can increase nums2 to match nums1's minimum possible sum
            # But wait, we can only increase nums2 if cnt2 > 0, otherwise impossible
            if cnt2 == 0:
                return -1 if sum1 != sum2 else sum1
            else:
                # We can increase nums2 to match nums1's minimum possible sum
                # But we need to check if sum2 + cnt2 >= sum1
                # Actually, we need to make them equal, so we need sum2 + cnt2 >= sum1
                # But we can also increase nums2 beyond sum1 if needed
                # The minimum equal sum would be max(sum1, sum2 + cnt2)
                # But wait, we can only increase nums2, so if sum2 + cnt2 < sum1, impossible
                # Otherwise, we can make nums2 equal to sum1
                if sum2 + cnt2 < sum1:
                    return -1
                else:
                    return sum1

        # If nums2 has no zeros, we can only increase nums1 if needed
        if cnt2 == 0:
            if sum1 + cnt1 < sum2:
                return -1
            else:
                return sum2

        # Both have zeros
        # We can increase either array
        # Minimum equal sum is max(sum1 + cnt1, sum2 + cnt2)
        return max(sum1 + cnt1, sum2 + cnt2)

