class Solution:
    def getWordsInLongestSubsequence(self, n: int, words: List[str], groups: List[int]) -> List[str]:
        res = [words[0]]
        group = groups[0]

        for i in range(1, n):
            if groups[i] != group:
                res.append(words[i])
                group = groups[i]

        return res

