class Solution:
    def minimumPossibleSum(self, n: int, target: int) -> int:
        k = target // 2

        if n <= k:
            return n * (n + 1) // 2
        else:
            sum1 = k * (k + 1) // 2
            sum2 = (2 * target + n - k - 1) * (n - k) // 2
            return sum1 + sum2

