import bisect

class Solution:
    def minAbsoluteDifference(self, nums: List[int], x: int) -> int:
        if x == 0:
            return 0

        res = float('inf')
        S = []

        # Loop over i from 0 to len(nums)-1
        for i in range(len(nums)):
            # Add nums[i-x] to S if i >= x (so we have at least x indices apart)
            if i >= x:
                bisect.insort(S, nums[i - x])

            # Find the position where nums[i] would be inserted
            j = bisect.bisect_left(S, nums[i])

            # Check if j is within bounds
            if j < len(S):
                res = min(res, abs(S[j] - nums[i]))

            # Check if j-1 is within bounds
            if j > 0:
                res = min(res, abs(S[j - 1] - nums[i]))

        return res

