class Solution:
    def countCompleteSubarrays(self, nums: List[int]) -> int:
        n = len(nums)
        m = len(set(nums))
        ans = 0

        # Outer loop: starting index of subarray
        for i in range(n):
            sub_set = set()
            # Inner loop: ending index of subarray
            for j in range(i, n):
                # Add current element to the set
                sub_set.add(nums[j])
                # Check if we have all distinct elements from the original array
                if len(sub_set) == m:
                    ans += 1

        return ans

