class Solution:
    def maxArrayValue(self, nums: List[int]) -> int:
        i = len(nums) - 2
        res = max(nums)

        while i >= 0:
            if nums[i + 1] >= nums[i]:
                nums[i] += nums[i + 1]
                res = max(res, nums[i])
            i -= 1

        return res

