class Solution:
    def sortVowels(self, s: str) -> str:
        # Define vowels (both lowercase and uppercase)
        vowels = set('aeiouAEIOU')

        # Collect all vowels from the string and sort them by ASCII value
        vowel_list = []
        for char in s:
            if char in vowels:
                vowel_list.append(char)

        # Sort the vowel list by ASCII value
        vowel_list.sort()

        # Build result string
        result = []
        vowel_index = 0

        for char in s:
            if char in vowels:
                # Replace vowel with next vowel from sorted list
                result.append(vowel_list[vowel_index])
                vowel_index += 1
            else:
                # Keep consonant as is
                result.append(char)

        return ''.join(result)

