class Solution:
    def maximumBeauty(self, nums: List[int], k: int) -> int:
        nums.sort()
        n = len(nums)
        left = 0
        ans = 0

        for i in range(n):
            # Check if we need to move left pointer
            if nums[left] < nums[i] - 2 * k:
                left += 1

            # Update answer with current window size
            ans = max(ans, i - left + 1)

        return ans

