class Solution:
    def minimumIndex(self, nums: List[int]) -> int:
        n = len(nums)

        # Find the dominant element (the one that satisfies freq * 2 > n)
        freq_map = {}
        for num in nums:
            freq_map[num] = freq_map.get(num, 0) + 1

        # Find the dominant element
        dominant = None
        for num, freq in freq_map.items():
            if freq * 2 > n:
                dominant = num
                break

        # Now check each possible split point
        for i in range(n - 1):  # i from 0 to n-2
            # Count frequency of dominant element in left part [0...i]
            left_freq = 0
            for j in range(i + 1):
                if nums[j] == dominant:
                    left_freq += 1

            # Count frequency of dominant element in right part [i+1...n-1]
            right_freq = freq_map[dominant] - left_freq

            # Check if both parts are valid
            left_valid = left_freq * 2 > (i + 1)
            right_valid = right_freq * 2 > (n - i - 1)

            if left_valid and right_valid:
                return i

        return -1

