class Solution:
    def numberOfPowerfulInt(self, start: int, finish: int, limit: int, s: str) -> int:
        def dp(i, mx):
            # Base case: if we've reached the end of mx and have exactly the right length for s
            if len(mx) - i == len(s):
                # Check if the suffix matches or exceeds s
                if mx[-len(s):] >= s:
                    return 1
                else:
                    return 0

            # If we have more positions than needed
            if len(mx) - i > len(s):
                ans = 0
                # Try all possible digits from 0 to limit
                for dig in range(limit + 1):
                    # Check if this digit can be placed here (considering leading zeros)
                    if i == 0 and dig == 0:
                        # Skip leading zero case (unless it's the only digit)
                        continue

                    # Check if this digit is <= the current digit in mx
                    if i < len(mx) and str(dig) <= mx[i]:
                        # Create new_mx by replacing the current digit or using '9' for maximization
                        new_mx = mx[:i] + str(dig) + mx[i+1:]
                        # If we're placing a digit smaller than current, we can use '9' for remaining positions
                        if i < len(mx) and str(dig) < mx[i]:
                            new_mx = mx[:i] + str(dig) + '9' * (len(mx) - i - 1)
                        ans += dp(i + 1, new_mx)
                    else:
                        # Continue to next iteration
                        continue

                return ans

            return 0

        # Convert start and finish to strings for easier manipulation
        finish_str = str(finish)
        start_str = str(start - 1)

        # Calculate result as dp(0, finish_str) - dp(0, start_str)
        return dp(0, finish_str) - dp(0, start_str)

