class Solution:
    def maxFrequencyScore(self, nums: List[int], k: int) -> int:
        nums.sort()
        n = len(nums)

        # Binary search on the answer (maximum frequency)
        left, right = 1, n

        while left < right:
            mid = (left + right + 1) // 2

            # Check if we can achieve frequency mid
            if self.canAchieveFrequency(nums, k, mid):
                left = mid
            else:
                right = mid - 1

        return left

    def canAchieveFrequency(self, nums, k, target_freq):
        n = len(nums)

        # Try every possible window of size target_freq
        for i in range(n - target_freq + 1):
            # Calculate minimum cost to make elements from i to i+target_freq-1 equal to some value
            # The optimal value is the median of these elements
            window = nums[i:i + target_freq]

            # Cost to make all elements in window equal to median
            median = window[target_freq // 2]  # For odd length, median is middle element

            cost = 0
            for num in window:
                cost += abs(num - median)

            if cost <= k:
                return True

        return False

