class Solution:
    def numberOfGoodPartitions(self, nums: List[int]) -> int:
        # Create a dictionary mapping each number to its last occurrence index
        last = {x: i for i, x in enumerate(nums)}

        # Initialize variables
        ii = -1  # rightmost boundary of current partition
        p = -1   # count of partitions minus one

        # Iterate through each index
        for i, x in enumerate(nums):
            # If current index is beyond the current partition boundary,
            # we need to start a new partition
            if ii < i:
                p += 1

            # Extend the current partition to include all occurrences of x
            ii = max(ii, last[x])

        # Return 2^p modulo 10^9 + 7
        return pow(2, p, 1_000_000_007)

