class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        max_xor = 0

        # Check all pairs (including same element twice)
        for i in range(len(nums)):
            for j in range(len(nums)):
                x, y = nums[i], nums[j]

                # Check if it's a strong pair
                if abs(x - y) <= min(x, y):
                    max_xor = max(max_xor, x ^ y)

        return max_xor

