from typing import List
from collections import defaultdict
import functools

class Solution:
    def maximumPoints(self, edges: List[List[int]], coins: List[int], k: int) -> int:
        n = len(coins)

        # Build adjacency list
        adj_list = defaultdict(list)
        for a, b in edges:
            if a > b:
                a, b = b, a
            adj_list[a].append(b)

        # Memoization decorator
        @functools.lru_cache(maxsize=None)
        def dp(node, floors):
            # If we've applied floor division 13 times or more, return 0
            if floors >= 13:
                return 0

            # Calculate current coin value after applying floor division 'floors' times
            c = coins[node]
            for _ in range(floors):
                c //= 2

            # Option 1: Take coins[i] - k points
            no_floor = c - k

            # Option 2: Take floor(coins[i] / 2) points and increase floors by 1
            floor_val = c // 2
            new_floors = floors + 1

            # Get maximum points from children for both options
            total_points = 0
            for child in adj_list[node]:
                total_points += dp(child, floors)

            # Return maximum of both options
            return max(no_floor + total_points, floor_val + total_points)

        return dp(0, 0)

