class Solution:
    def maxIncreasingGroups(self, usageLimits: List[int]) -> int:
        usageLimits.sort()
        n = len(usageLimits)
        ans = 0
        totalgroup = 0

        for i in range(n):
            totalgroup += usageLimits[i]
            seen = (ans + 1) * (ans + 2) // 2
            if totalgroup >= seen:
                ans += 1

        return ans

