class Solution:
    def sumImbalanceNumbers(self, nums: List[int]) -> int:
        n = len(nums)
        r = 0

        for i in range(n):
            s = set()
            temp = -1

            for j in range(i, n):
                # Check if nums[j] is not in s
                if nums[j] not in s:
                    s.add(nums[j])
                    # Update temp based on neighbors
                    temp += 1 - (nums[j] + 1 in s) - (nums[j] - 1 in s)
                # Update r with current temp
                r += temp

        return r
